describe('proof', function () {
  it('fails on the patched build', function () {
    // Garbage before a valid size must not be parsed. The unanchored
    // regex matches "1kb" at the end, so the patched build returns
    // 1024 instead of null.
    assert.strictEqual(bytes.parse('invalid 1kb'), null);

    // An embedded sign is also captured once '^' is removed:
    // patched build returns -2 * 1024 * 1024 instead of null.
    assert.strictEqual(bytes.parse('abc-2mb'), null);
  });
});

