var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('fails on the patched build', function () {
    // Non-string values must be rejected even when they have a length property.
    assert.throws(function () {
      ms(['100']);
    });
    assert.throws(function () {
      ms({ length: 2 });
    });
    assert.throws(function () {
      ms(new String('100'));
    });
    // null/undefined must produce the documented error, not a TypeError.
    assert.throws(function () {
      ms(null);
    }, /val is not a non-empty string or a valid number/);
    assert.throws(function () {
      ms(undefined);
    }, /val is not a non-empty string or a valid number/);
  });
});

